import fs from 'node:fs';
import path from 'node:path';

/**
 * Stand-ins for what an Electron release zip carries at its root — LICENSE,
 * LICENSES.chromium.html and version — and for the parts of a packaged
 * macOS app scripts/electron-licences.js reads. Shaped like the real files
 * (electron-v31.7.7-darwin-arm64.zip: Electron's LICENSE is the MIT text
 * under its two copyright lines; Chromium's credits page is generated by
 * licenses.py, titled "Credits", and lists each product in a
 * class="product" block), but small, and built here rather than copied.
 */

const REPO = path.join(__dirname, '..', '..');

/** Electron's licence: the MIT text of TreeMap's own LICENSE, under Electron's copyright lines. */
export function electronLicence(): Buffer {
  const own = fs.readFileSync(path.join(REPO, 'LICENSE'), 'utf8').replace(/\r\n/g, '\n');
  const at = own.indexOf('Permission is hereby granted');
  if (at === -1) throw new Error('LICENSE has no MIT grant to build the fixture from');
  return Buffer.from(`Copyright (c) Electron contributors\nCopyright (c) 2013-2020 GitHub Inc.\n\n${own.slice(at)}`);
}

/** A page shaped like Chromium's credits, listing `products` products. */
export function chromiumCredits(products = 120): Buffer {
  const head = [
    '<!-- Generated by licenses.py; do not edit. --><!doctype html>',
    '<html>',
    '<head>',
    '<meta charset="utf-8">',
    '<title>Credits</title>',
    '</head>',
    '<body>',
    '<span class="page-title">Credits</span>',
  ].join('\n');
  const body = Array.from(
    { length: products },
    (_, i) => `<div class="product">\n<span class="title">Product ${i}</span>\n<div class="licence"><pre>Licence text ${i}</pre></div>\n</div>`,
  ).join('\n');
  return Buffer.from(`${head}\n${body}\n</body>\n</html>\n`);
}

/** The Electron Framework's Info.plist, in the XML form Electron ships it, for `version`. */
export function electronFrameworkPlist(version: string): string {
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">',
    '<plist version="1.0">',
    '<dict>',
    '\t<key>CFBundleIdentifier</key>',
    '\t<string>com.github.Electron.framework</string>',
    '\t<key>CFBundleVersion</key>',
    `\t<string>${version}</string>`,
    '</dict>',
    '</plist>',
    '',
  ].join('\n');
}

/** Where a packaged macOS app keeps its Electron Framework's Info.plist. */
export function frameworkPlistPath(app: string): string {
  return path.join(app, 'Contents', 'Frameworks', 'Electron Framework.framework', 'Resources', 'Info.plist');
}

/**
 * What electron-builder leaves in `appOutDir` for a macOS app when afterPack
 * runs: the bundle, its Resources folder, and its Electron Framework holding
 * Electron `electronVersion` — and, as electron-builder's createMacApp
 * leaves it, no LICENSE or LICENSES.chromium.html anywhere.
 */
export function macAppLayout(appOutDir: string, productFilename: string, electronVersion: string): { app: string; resources: string } {
  const app = path.join(appOutDir, `${productFilename}.app`);
  const resources = path.join(app, 'Contents', 'Resources');
  fs.mkdirSync(resources, { recursive: true });
  fs.mkdirSync(path.dirname(frameworkPlistPath(app)), { recursive: true });
  fs.writeFileSync(frameworkPlistPath(app), electronFrameworkPlist(electronVersion));
  return { app, resources };
}

/** The three entries an Electron release zip carries at its root, for `version`. */
export function electronZipEntries(version: string): Record<'LICENSE' | 'LICENSES.chromium.html' | 'version', Buffer> {
  return { LICENSE: electronLicence(), 'LICENSES.chromium.html': chromiumCredits(), version: Buffer.from(version) };
}
